import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"Tools and skills","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tools.md","filePath":"guide/tools.md"}'),n={name:"guide/tools.md"};function l(o,a,r,d,h,c){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="tools-and-skills" tabindex="-1">Tools and skills <a class="header-anchor" href="#tools-and-skills" aria-label="Permalink to &quot;Tools and skills&quot;">​</a></h1><p>MCP tools let an agent act through gateway integrations. Skills are Markdown instructions that teach an agent how to carry out a workflow with those tools.</p><h2 id="verify-tools-are-available" tabindex="-1">Verify tools are available <a class="header-anchor" href="#verify-tools-are-available" aria-label="Permalink to &quot;Verify tools are available&quot;">​</a></h2><p>Bun runs <code>mcp/server.ts</code>; its dependencies must be installed. After installation, ask an agent to list its available tools and try one read-only operation, such as listing cron jobs. Check the result rather than treating an announced intention as execution.</p><p>If tools are unavailable, check <code>bun --version</code>, MCP dependency installation, and the agent logs. In a source checkout, <code>make mcp-install</code> installs the MCP dependencies.</p><h2 id="add-a-skill" tabindex="-1">Add a skill <a class="header-anchor" href="#add-a-skill" aria-label="Permalink to &quot;Add a skill&quot;">​</a></h2><p>Create <code>skills/review-notes/SKILL.md</code> inside the agent workspace:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: review-notes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Review project notes and identify unanswered questions.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Read the relevant notes before summarizing.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Separate confirmed decisions from unanswered questions.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Link each finding to its source file.</span></span></code></pre></div><p>Skills hot-reload. Ask the agent to review a small note and verify that its answer cites the file. Agent-specific and shared skill locations are documented in the <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/README.md#agent-skills" target="_blank" rel="noreferrer">skill reference</a>.</p><h2 id="automatic-skill-learning" tabindex="-1">Automatic skill learning <a class="header-anchor" href="#automatic-skill-learning" aria-label="Permalink to &quot;Automatic skill learning&quot;">​</a></h2><p><code>gateway.skillLearning</code> controls background review of substantive work. It can create or update automatically learned skills, with daily and total limits and an audit in <code>SKILLS_LEARNED.md</code>. The provenance guard preserves human-authored skills. Review the audit when evaluating what the agent learned.</p><p>Connector availability and agent tool permissions also affect what a session can do. See <a href="./../reference/configuration.html">configuration</a> and the <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/README.md#mcp-tool-system" target="_blank" rel="noreferrer">full tool architecture</a>.</p>`,12)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
